ALTER TABLE beta_settings ADD COLUMN quota_enforced INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS monthly_estimation_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, period_key TEXT NOT NULL, idempotency_key TEXT NOT NULL, consumed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,period_key,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS premium_interest (user_id INTEGER PRIMARY KEY, consent INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
